create table public.activity_attempts (id uuid primary key default gen_random_uuid(), activity_id uuid not null references public.activities(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, started_at timestamptz not null default now(), submitted_at timestamptz, response jsonb, evaluation jsonb, score numeric(6,2) check (score between 0 and 100), completion_state text not null default 'started', attempt_number integer not null default 1 check (attempt_number > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
